// Metadata-ONLY backfill (no re-embedding, no vector insert/delete).
//
// BUG FIX (2026-08-19, after a real run corrupted 11 rows across 4 calls):
// this originally used `$('Fetch Transcript').item.json` inside a manual
// `.forEach()` loop. `.item` resolves ONCE for the whole runOnceForAllItems
// execution — it does NOT re-pair per iteration of a hand-rolled loop. When
// multiple calls' existing-chunk rows converged into one execution (Limit(5)
// over 5 calls, each expanding to N rows via Get Existing Chunks), every item
// after the first silently got the FIRST call's transcript/timing, producing
// plausible-looking but WRONG start_ms/end_ms for every other call. Fixed by
// resolving each item's true originating call via `itemMatching(idx)` (the
// correct n8n API for exactly this case), then grouping items by their
// resolved call_id before computing anything — this also fixes a second,
// subtler bug: the proportional-fallback math used the GLOBAL item index/count
// across the whole batch, not this call's own chunk index/count, which would
// have been wrong even with pairing fixed.
const inputItems = $input.all();

const resolved = inputItems.map((item, idx) => ({
  item,
  raw: $('Fetch Transcript').itemMatching(idx).json,
}));

const groups = new Map();
for (const r of resolved) {
  const callId = r.raw.call_id;
  if (!groups.has(callId)) groups.set(callId, { raw: r.raw, items: [] });
  groups.get(callId).items.push(r.item);
}

const results = [];

for (const [callId, group] of groups) {
  const raw = group.raw;
  const parties = raw.parties || [];
  const transcript = raw.transcript || [];

  const speakerLabels = {};
  parties.forEach((p, i) => {
    const affiliation = p.affiliation || 'Unknown';
    const label = (p.name || 'Speaker ' + (i + 1)) + ' (' + affiliation + ')';
    if (p.speakerId !== undefined && p.speakerId !== null) speakerLabels[p.speakerId] = label;
  });

  const segments = [];
  const lines = [];
  let cursor = 0;
  for (const turn of transcript) {
    const sentences = turn.sentences || [];
    if (sentences.length === 0) continue;
    const speaker = speakerLabels[turn.speakerId] || ('Speaker ' + turn.speakerId);
    const topic = turn.topic ? ' [' + turn.topic + ']' : '';
    const sentenceText = sentences.map(s => s.text).join(' ');
    const line = speaker + topic + ': ' + sentenceText;
    const startMs = Number(sentences[0].start);
    const endMs = Number(sentences[sentences.length - 1].end);
    const charStart = cursor;
    const charEnd = cursor + line.length;
    segments.push({ charStart, charEnd, startMs, endMs });
    lines.push(line);
    cursor = charEnd + 2; // '\n\n' separator, matches Prepare Calls join
  }
  const transcriptText = lines.join('\n\n');
  const totalStart = segments.length ? segments[0].startMs : null;
  const totalEnd = segments.length ? segments[segments.length - 1].endMs : null;

  const n = group.items.length;
  group.items.forEach((item, idx) => {
    const row = item.json;
    const content = row.content || '';
    let startMs = null, endMs = null, method = 'unmatched';

    const foundIndex = content ? transcriptText.indexOf(content) : -1;
    if (foundIndex >= 0) {
      const matchStart = foundIndex;
      const matchEnd = foundIndex + content.length;
      const overlapping = segments.filter(s => s.charStart < matchEnd && s.charEnd > matchStart);
      if (overlapping.length > 0) {
        startMs = Math.min(...overlapping.map(s => s.startMs));
        endMs = Math.max(...overlapping.map(s => s.endMs));
        method = 'exact';
      }
    }

    if (startMs === null && totalStart !== null && totalEnd !== null) {
      const frac0 = n > 0 ? idx / n : 0;
      const frac1 = n > 0 ? (idx + 1) / n : 1;
      const span = totalEnd - totalStart;
      startMs = totalStart + span * frac0;
      endMs = totalStart + span * frac1;
      method = 'proportional_fallback';
    }

    results.push({
      json: { id: row.id, start_ms: startMs, end_ms: endMs, method, call_id: callId }
    });
  });
}

return results;
